  COVER_SECONDS: 1.4,
  PATROL_SPEED: 3.3,
  ENGAGE_SPEED: 2.4,
  WAYPOINT_RADIUS: 1.5,
});

// --- Match presentation -----------------------------------------------------------
export const UI = Object.freeze({
  RADAR_SCALE: 2.9, // pixels per metre on the radar
  FEED_LINES: 5,
  FEED_SECONDS: 5.5,
  TRACE_REFRESH: 0.2,
});
