/* style.css — the HUD's whole look: one palette, one type scale, flat panels.
   The 3D scene owns the colour of the world; this file owns the colour of the readout,
   and it only ever uses the six variables below, so the HUD cannot drift off-palette. */

:root {
  --canvas: #0e181a;
  --panel: rgba(13, 24, 26, 0.78);
  --panel-solid: #101d1f;
  --hairline: rgba(236, 229, 212, 0.16);
  --ink: #ece5d4;
  --muted: #93a19d;
  --accent: #f0a63c;
  --ally: #4fb3bd;
  --enemy: #d0743c;
  --good: #8fd6b0;
  --font-ui: system-ui, -apple-system, 'Segoe UI', sans-serif;
  --font-read: ui-monospace, 'SF Mono', Menlo, Consolas, monospace;
}

* { box-sizing: border-box; }
html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: var(--canvas);
  color: var(--ink);
  font-family: var(--font-ui);
