#crosshair i:nth-child(1) { transform: translateY(calc(-1 * var(--gap))); }
#crosshair i:nth-child(2) { transform: translateY(var(--gap)); }
#crosshair i:nth-child(3) { transform: translateX(calc(-1 * var(--gap))); }
#crosshair i:nth-child(4) { transform: translateX(var(--gap)); }

#hitmarker {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  font-family: var(--font-read);
  font-size: 30px;
  font-weight: 700;
  color: var(--accent);
  opacity: 0;
  text-shadow: 0 0 8px rgba(0, 0, 0, 0.9);
  transition: opacity 70ms linear;
}

#progress {
  position: absolute;
  left: 50%;
  top: 104px;
  transform: translateX(-50%);
  width: 264px;
  padding: 7px 10px 9px;
  text-align: center;
  background: var(--panel-solid);
  border: 1px solid var(--hairline);
}
#progress[hidden] { display: none; }
#progress span {
  font-family: var(--font-read);
  font-size: 9px;
  letter-spacing: 2px;
  color: var(--accent);
}
#progress div {
  margin-top: 5px;
  height: 5px;
  background: rgba(13, 24, 26, 0.85);
  border: 1px solid var(--hairline);
}
#progress i { display: block; height: 100%; width: 0; background: var(--accent); }

/* --- Bottom console ------------------------------------------------------------- */
.console {
  position: absolute;
  left: 28px;
  right: 28px;
  bottom: 30px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
}
.console > div {
  background: var(--panel);
  border: 1px solid var(--hairline);
  padding: 8px 14px;
}
.vitals { min-width: 168px; }
.vitals div { display: flex; align-items: baseline; gap: 10px; }
.vitals strong { font-family: var(--font-read); font-size: 30px; font-weight: 500; line-height: 1; }
.vitals .armor { font-family: var(--font-read); font-size: 11px; color: var(--ally); }
.vitals i { display: block; margin-top: 6px; height: 3px; background: rgba(236, 229, 212, 0.14); }
.vitals i b { display: block; height: 100%; width: 100%; background: var(--good); }

.funds { text-align: center; }
.funds b { display: block; font-family: var(--font-read); font-size: 19px; font-weight: 500; color: var(--accent); }
.funds span { font-family: var(--font-read); font-size: 8px; letter-spacing: 1.4px; color: var(--muted); }

.loadout { min-width: 190px; text-align: right; }
.loadout small { display: block; color: var(--ink); letter-spacing: 1.8px; }
.loadout div { display: flex; align-items: baseline; justify-content: flex-end; gap: 6px; }
.loadout strong { font-family: var(--font-read); font-size: 32px; font-weight: 500; line-height: 1; }
.loadout span { font-family: var(--font-read); font-size: 12px; color: var(--muted); }

.statusline {
  position: absolute;
  left: 28px;
  right: 28px;
  bottom: 0;
  padding: 7px 12px 8px;
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-family: var(--font-read);
  font-size: 9px;
  letter-spacing: 1.4px;
  color: var(--muted);
  background: linear-gradient(180deg, rgba(8, 15, 17, 0) 0%, rgba(8, 15, 17, 0.86) 40%, rgba(8, 15, 17, 0.94) 100%);
}
#status { color: var(--accent); }
.statusline .keys { letter-spacing: 1px; opacity: 0.75; }
#stance { color: var(--ally); }

/* --- Overlays ------------------------------------------------------------------- */
#buy, #start, #result, #pause {
  position: fixed;
  inset: 0;
  background: rgba(8, 15, 17, 0.92);
  color: var(--ink);
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 44px 64px;
}
#buy[hidden], #start[hidden], #result[hidden], #pause[hidden] { display: none; }
#buy { cursor: pointer; pointer-events: auto; }

#buy header, #result header {
  display: flex;
  justify-content: space-between;
  font-family: var(--font-read);
  font-size: 10px;
  letter-spacing: 2px;
  color: var(--muted);
  padding-bottom: 12px;
  border-bottom: 1px solid var(--hairline);
}
#buy h1, #result h1 {
  margin: 22px 0 6px;
  font-size: 40px;
  font-weight: 700;
  letter-spacing: -0.02em;
}
#buy > p { margin: 0 0 22px; font-size: 14px; color: var(--muted); }
#buy .items { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; }
#buy article {
  position: relative;
  padding: 16px 18px 14px;
  background: rgba(20, 34, 36, 0.9);
  border: 1px solid var(--hairline);
}
#buy article kbd {
  position: absolute;
  right: 14px;
  top: 14px;
  width: 22px;
  height: 22px;
  display: grid;
  place-items: center;
  font-family: var(--font-read);
  font-size: 11px;
  color: var(--canvas);
  background: var(--ink);
}
#buy article h2 { margin: 0; font-size: 21px; font-weight: 700; letter-spacing: 0.02em; }
#buy article small { display: block; margin: 2px 0 10px; color: var(--accent); }
#buy article p { margin: 0 0 12px; font-size: 12px; line-height: 1.5; color: var(--muted); }
#buy article b { font-family: var(--font-read); font-size: 15px; color: var(--ink); }
#buy footer, #result footer {
  display: flex;
  justify-content: space-between;
  margin-top: 22px;
  font-family: var(--font-read);
  font-size: 10px;
  letter-spacing: 1.8px;
  color: var(--muted);
}
#buy footer span { color: var(--accent); }

#start { align-items: flex-start; background: linear-gradient(100deg, rgba(8, 15, 17, 0.97) 0%, rgba(8, 15, 17, 0.86) 55%, rgba(8, 15, 17, 0.4) 100%); }
#start small { color: var(--accent); letter-spacing: 3px; }
#start h1 {
  margin: 14px 0 10px;
  font-size: 76px;
  font-weight: 800;
  letter-spacing: 8px;
  line-height: 1;
}
#start > p { margin: 0 0 26px; max-width: 46ch; font-size: 16px; line-height: 1.55; color: var(--muted); }
#start .brief { display: flex; gap: 12px; max-width: 720px; margin-bottom: 28px; }
#start .brief div {
  flex: 1;
  padding: 12px 14px;
  background: rgba(20, 34, 36, 0.8);
  border-top: 2px solid var(--accent);
  font-size: 12px;
  line-height: 1.5;
  color: var(--muted);
}
#start .brief b { display: block; margin-bottom: 4px; font-size: 10px; letter-spacing: 2px; color: var(--ink); }
#play {
  align-self: flex-start;
  padding: 14px 26px;
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 3px;
  color: var(--canvas);
  background: var(--accent);
  border: 0;
  cursor: pointer;
}
#play:hover { background: var(--ink); }
#start aside {
  margin-top: 22px;
  font-family: var(--font-read);
  font-size: 10px;
  line-height: 1.9;
  letter-spacing: 1.2px;
  color: var(--muted);
}

#pause {
  align-items: center;
  justify-content: center;
  text-align: center;
  font-family: var(--font-read);
  font-size: 18px;
  letter-spacing: 6px;
  background: rgba(8, 15, 17, 0.72);
  pointer-events: none;
}
#pause span { display: block; margin-top: 12px; font-size: 10px; letter-spacing: 2px; color: var(--muted); }

#result { justify-content: center; background: rgba(8, 15, 17, 0.955); padding: 36px 72px; }
#result h1 { margin: 16px 0 2px; font-size: 46px; letter-spacing: 2px; }
#result > p { margin: 0 0 16px; font-family: var(--font-read); font-size: 12px; letter-spacing: 1.4px; color: var(--accent); }
#result table {
  width: 100%;
  border-collapse: collapse;
  font-family: var(--font-read);
  font-size: 12px;
  background: rgba(20, 34, 36, 0.85);
  border: 1px solid var(--hairline);
}
#result thead th {
  padding: 9px 12px;
  text-align: left;
  font-weight: 400;
  font-size: 9px;
  letter-spacing: 1.8px;
  color: var(--muted);
  border-bottom: 1px solid var(--hairline);
}
#result thead th:nth-child(n + 2) { text-align: right; }
#result tbody td { padding: 8px 12px; border-bottom: 1px solid rgba(236, 229, 212, 0.07); }
#result tbody td:nth-child(n + 2) { text-align: right; }
#result tbody tr:last-child td { border-bottom: 0; }
#result tbody tr.team td {
  padding: 7px 12px;
  font-size: 10px;
  letter-spacing: 2.4px;
  text-align: left;
  background: rgba(236, 229, 212, 0.06);
  border-bottom: 1px solid var(--hairline);
}
#result tbody tr.team.ally td { color: var(--ally); }
#result tbody tr.team.enemy td { color: var(--enemy); }
#result tbody tr.me td { color: var(--ally); }
#result tbody tr.me { background: rgba(79, 179, 189, 0.08); }
#result tbody tr.down td { color: #a6b4b1; }
#result tbody tr.down td:first-child { text-decoration: line-through; }
#result footer span:last-child { color: var(--accent); }

/* While the debrief is up, the live HUD steps aside so the board is the only thing read. */
#hud.veiled > * { opacity: 0; }

@media (prefers-reduced-motion: reduce) {
  #damage, #hitmarker { transition-duration: 0.01ms; }
}
